1	import type { PortfolioData } from '../types/portfolio';
2	import { initialData } from '../data/initialData';
3	
4	const STORAGE_KEY = 'portfolio_data';
5	
6	export const storage = {
7	    // Get all portfolio data
8	    getData: (): PortfolioData => {
9	        try {
10	            const data = localStorage.getItem(STORAGE_KEY);
11	            if (data) {
12	                return JSON.parse(data);
13	            }
14	            // Initialize with default data if not exists
15	            storage.setData(initialData);
16	            return initialData;
17	        } catch (error) {
18	            console.error('Error reading from localStorage:', error);
19	            return initialData;
20	        }
21	    },
22	
23	    // Set all portfolio data
24	    setData: (data: PortfolioData): void => {
25	        try {
26	            localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
27	        } catch (error) {
28	            console.error('Error writing to localStorage:', error);
29	        }
30	    },
31	
32	    // Update specific section
33	    updateSection: <K extends keyof PortfolioData>(
34	        section: K,
35	        data: PortfolioData[K]
36	    ): void => {
37	        const currentData = storage.getData();
38	        currentData[section] = data;
39	        storage.setData(currentData);
40	    },
41	
42	    // Reset to initial data
43	    reset: (): void => {
44	        storage.setData(initialData);
45	    },
46	
47	    // Export data as JSON
48	    exportData: (): string => {
49	        return JSON.stringify(storage.getData(), null, 2);
50	    },
51	
52	    // Import data from JSON
53	    importData: (jsonString: string): boolean => {
54	        try {
55	            const data = JSON.parse(jsonString) as PortfolioData;
56	            storage.setData(data);
57	            return true;
58	        } catch (error) {
59	            console.error('Error importing data:', error);
