import { initializeApp } from 'firebase/app';
import { initializeFirestore } from 'firebase/firestore';
import { getAuth } from 'firebase/auth';
import { getStorage } from 'firebase/storage';

const env = import.meta.env;

// Without a .env the app still has to boot — getStorage() throws on an empty
// bucket, which would blank the whole page. Fall back to placeholders and let
// callers check isFirebaseConfigured before hitting the network.
export const isFirebaseConfigured = Boolean(
    env.VITE_FIREBASE_API_KEY &&
    env.VITE_FIREBASE_PROJECT_ID &&
    env.VITE_FIREBASE_STORAGE_BUCKET &&
    env.VITE_FIREBASE_APP_ID
);

if (!isFirebaseConfigured) {
    console.warn(
        '⚠️ Firebase is not configured (missing .env). Running on demo data from src/data/initialData.ts — changes will not be saved.'
    );
}

const firebaseConfig = {
    apiKey: env.VITE_FIREBASE_API_KEY ?? 'demo-api-key',
    authDomain: env.VITE_FIREBASE_AUTH_DOMAIN ?? 'demo.firebaseapp.com',
    projectId: env.VITE_FIREBASE_PROJECT_ID ?? 'demo-project',
    storageBucket: env.VITE_FIREBASE_STORAGE_BUCKET ?? 'demo-project.appspot.com',
    messagingSenderId: env.VITE_FIREBASE_MESSAGING_SENDER_ID ?? '000000000000',
    appId: env.VITE_FIREBASE_APP_ID ?? '1:000000000000:web:0000000000000000000000',
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);

// Initialize Firestore
export const db = initializeFirestore(app, {
    experimentalForceLongPolling: true,
});

// Initialize Auth
export const auth = getAuth(app);

// Initialize Storage
export const storage = getStorage(app);

