import { ref, uploadBytes, uploadString, getDownloadURL, deleteObject } from 'firebase/storage';
import { storage, isFirebaseConfigured } from '../config/firebaseConfig';
import { compressImage } from '../utils/fileUtils';

// Images live in Storage now rather than inside the Firestore document, so they
// no longer compete for the 1 MB document budget. That means we can size them
// for high-DPI screens instead of shrinking to the smallest thing that renders.
const PRESETS = {
    profile: { maxWidth: 1200, quality: 0.9 },
    project: { maxWidth: 1600, quality: 0.88 },
    icon: { maxWidth: 256, quality: 0.92 },
} as const;

export type ImageKind = keyof typeof PRESETS;

const extensionFor = (file: File): string => {
    const fromName = file.name.split('.').pop()?.toLowerCase();
    if (fromName && fromName.length <= 4) return fromName;
    return file.type.split('/')[1] || 'bin';
};

/**
 * Uploads an image to Firebase Storage and returns its public download URL.
 * Only that URL is stored in Firestore.
 */
export const uploadImage = async (
    file: File,
    kind: ImageKind,
    folder: string
): Promise<string> => {
    if (!isFirebaseConfigured) {
        throw new Error('Firebase is not configured, so images cannot be uploaded.');
    }

    // SVGs are vector and icons are usually PNGs with transparency. Routing
    // either through the canvas would rasterize or flatten them onto black,
    // so upload those untouched — they are small to begin with.
    const uploadRaw = file.type === 'image/svg+xml' || kind === 'icon';
    const path = `${folder}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

    if (uploadRaw) {
        const objectRef = ref(storage, `${path}.${extensionFor(file)}`);
        await uploadBytes(objectRef, file, { contentType: file.type });
        return getDownloadURL(objectRef);
    }

    const { maxWidth, quality } = PRESETS[kind];
    const dataUrl = await compressImage(file, maxWidth, quality);
    const objectRef = ref(storage, `${path}.jpg`);
    await uploadString(objectRef, dataUrl, 'data_url');
    return getDownloadURL(objectRef);
};

/**
 * Best-effort cleanup so replaced images don't pile up in the bucket. Only
 * touches files in our own bucket — external URLs (Unsplash, etc.) are left
 * alone, and a failure here is never worth blocking the save for.
 */
export const deleteImageIfOwned = async (url: string | undefined): Promise<void> => {
    if (!url || !url.includes('firebasestorage.googleapis.com')) return;

    try {
        await deleteObject(ref(storage, url));
    } catch (error) {
        console.warn('Could not delete the previous image (it may already be gone):', error);
    }
};

