3	export const convertFileToBase64 = (file: File): Promise<string> => {
4	    return new Promise((resolve, reject) => {
5	        const reader = new FileReader();
6	        reader.readAsDataURL(file);
7	        reader.onload = () => resolve(reader.result as string);
8	        reader.onerror = (error) => reject(error);
9	    });
10	};
11	
12	export const compressImage = (file: File, maxWidth: number = 800, quality: number = 0.7): Promise<string> => {
13	    return new Promise((resolve, reject) => {
14	        const reader = new FileReader();
15	        reader.readAsDataURL(file);
16	        reader.onload = (event) => {
17	            const img = new Image();
18	            img.src = event.target?.result as string;
19	            img.onload = () => {
20	                const canvas = document.createElement('canvas');
21	                let width = img.width;
22	                let height = img.height;
23	
24	                if (width > maxWidth) {
25	                    height = (height * maxWidth) / width;
26	                    width = maxWidth;
27	                }
28	
29	                canvas.width = width;
30	                canvas.height = height;
31	
32	                const ctx = canvas.getContext('2d');
33	                if (!ctx) {
34	                    reject(new Error('Failed to get canvas context'));
35	                    return;
36	                }
37	
38	                ctx.drawImage(img, 0, 0, width, height);
39	                const compressedBase64 = canvas.toDataURL('image/jpeg', quality);
40	                resolve(compressedBase64);
41	            };
42	            img.onerror = (error) => reject(error);
43	        };
44	        reader.onerror = (error) => reject(error);
45	    });
46	};
47	
48	export const compressBase64 = (base64Str: string, maxWidth: number, quality: number): Promise<string> => {
49	    if (!base64Str || !base64Str.startsWith('data:image')) {
50	        return Promise.resolve(base64Str);
51	    }
52	    // SVGs are vector graphic code and do not need visual canvas compression
53	    if (base64Str.includes('image/svg+xml')) {
54	        return Promise.resolve(base64Str);
55	    }
56	    return new Promise((resolve) => {
57	        const img = new Image();
58	        img.src = base64Str;
59	        img.onload = () => {
60	            const canvas = document.createElement('canvas');
61	            let width = img.width;
62	            let height = img.height;
63	
64	            if (width > maxWidth) {
65	                height = (height * maxWidth) / width;
66	                width = maxWidth;
67	            }
68	
69	            canvas.width = width;
70	            canvas.height = height;
71	
72	            const ctx = canvas.getContext('2d');
73	            if (ctx) {
74	                ctx.drawImage(img, 0, 0, width, height);
75	                resolve(canvas.toDataURL('image/jpeg', quality));
76	            } else {
77	                resolve(base64Str);
78	            }
79	        };
80	        img.onerror = () => resolve(base64Str);
81	    });
82	};
83	
84	export const compressAllPortfolioData = async (data: PortfolioData): Promise<PortfolioData> => {
85	    const copy = JSON.parse(JSON.stringify(data)) as PortfolioData;
86	
87	    // 1. Profile images (max 300px, quality 0.5)
88	    if (copy.profile) {
89	        if (copy.profile.image) {
90	            copy.profile.image = await compressBase64(copy.profile.image, 300, 0.5);
91	        }
92	        if (copy.profile.aboutImage) {
93	            copy.profile.aboutImage = await compressBase64(copy.profile.aboutImage, 300, 0.5);
94	        }
95	    }
96	
97	    // 2. Skills icons (max 64px, quality 0.5)
98	    if (copy.skills && Array.isArray(copy.skills)) {
99	        for (let i = 0; i < copy.skills.length; i++) {
100	            const skill = copy.skills[i];
101	            if (skill.icon) {
102	                skill.icon = await compressBase64(skill.icon, 64, 0.5);
103	            }
104	        }
105	    }
106	
107	    // 3. Projects images (max 500px, quality 0.5)
108	    if (copy.projects && Array.isArray(copy.projects)) {
109	        for (let i = 0; i < copy.projects.length; i++) {
110	            const project = copy.projects[i];
111	            if (project.image) {
112	                project.image = await compressBase64(project.image, 500, 0.5);
113	            }
114	        }
115	    }
116	
117	    return copy;
118	};

