@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Outfit:wght@300;400;500;600;700;800;900&display=swap');

@import "tailwindcss";
@config "../tailwind.config.js";

@layer base {
  * {
    box-sizing: border-box;
  }

  html {
    scroll-behavior: smooth;
    overflow-x: hidden;
  }

  body {
    @apply bg-white dark:bg-gray-950 text-gray-900 dark:text-gray-100;
    @apply font-sans antialiased;
    overflow-x: hidden;
  }
}

@layer components {
  .glass {
    @apply bg-white/10 dark:bg-gray-900/10 backdrop-blur-lg;
    @apply border border-white/20 dark:border-gray-700/20;
  }

  .glass-strong {
    @apply bg-white/20 dark:bg-gray-900/20 backdrop-blur-xl;
    @apply border border-white/30 dark:border-gray-700/30;
  }

  .btn-primary {
    @apply px-6 py-3 rounded-lg font-semibold text-white;
    @apply bg-gradient-to-r from-primary-600 to-accent-600;
    @apply hover:from-primary-700 hover:to-accent-700;
    @apply transform hover:scale-105 transition-all duration-300;
    @apply shadow-lg hover:shadow-xl;
  }

  .btn-secondary {
    @apply px-6 py-3 rounded-lg font-semibold;
    @apply bg-gray-100 dark:bg-gray-800 text-gray-900 dark:text-gray-100;
    @apply hover:bg-gray-200 dark:hover:bg-gray-700;
    @apply transform hover:scale-105 transition-all duration-300;
  }

  .input-field {
    @apply w-full px-4 py-3 rounded-lg;
    @apply bg-white dark:bg-gray-800;
    @apply border-2 border-gray-200 dark:border-gray-700;
    @apply focus:border-primary-500 dark:focus:border-primary-400;
    @apply focus:ring-2 focus:ring-primary-500/20;
    @apply outline-none transition-all duration-300;
  }

  .card {
    @apply bg-white dark:bg-gray-800;
    @apply rounded-xl shadow-lg;
    @apply border border-gray-200 dark:border-gray-700;
    @apply p-6;
  }

  .card-hover {
    @apply bg-white dark:bg-gray-800;
    @apply rounded-xl shadow-lg;
    @apply border border-gray-200 dark:border-gray-700;
    @apply p-6;
    @apply transform hover:scale-105 hover:shadow-2xl;
    @apply transition-all duration-300;
  }

  .gradient-text {
    @apply bg-gradient-to-r from-primary-600 to-accent-600;
    @apply bg-clip-text text-transparent;
  }

  .section-padding {
    @apply py-20 px-4 md:px-8 lg:px-16;
  }
}

@layer utilities {
  .text-balance {
    text-wrap: balance;
  }
}

/* Custom Scrollbar */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  @apply bg-gray-100 dark:bg-gray-900;
}

::-webkit-scrollbar-thumb {
  @apply bg-gray-300 dark:bg-gray-700 rounded-full;
}

::-webkit-scrollbar-thumb:hover {
  @apply bg-gray-400 dark:bg-gray-600;
}

/* Smooth animations */
* {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* Reduced motion.
   Catches every CSS-driven animation and transition, including the infinite
   loops (animate-float, animate-gradient, animate-pulse, animate-ping) and the
   inline `fall` keyframes in SnowAnimation. Animations are collapsed rather
   than removed so any end-state styling still applies.

   This does NOT cover JavaScript-driven Motion animations, which ignore the
   media query. Those are handled per component with useReducedMotion(). */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

