                                                <img
                                                    src={skill.icon}
                                                    alt={skill.name}
                                                    className="w-full h-full object-contain"
                                                />
                                            )
                                        ) : iconUrl ? (
                                            <img
                                                src={iconUrl}
                                                alt={skill.name}
                                                className="w-full h-full object-contain"
